import datetime

def release_year(rd):
    if not rd:
        return None
    # handle YYYY or full ISO
    try:
        return datetime.datetime.fromisoformat(rd.replace('Z','+00:00')).year
    except Exception:
        try:
            return int(str(rd)[:4])
        except Exception:
            return None

